def read(p):
    with open(p, encoding="utf-8", newline="") as f:
        return f.read()


def write(p, s):
    with open(p, "w", encoding="utf-8", newline="") as f:
        f.write(s)


def main():
    files = list(EDITS)
    if not all(os.path.isfile(p) for p in files):
        sys.exit("Chay script nay o thu muc goc cua repo ai-live (noi co thu muc utils/).")
    if "--revert" in sys.argv:
        for p in files:
            if os.path.isfile(p + BAK):
                shutil.copyfile(p + BAK, p)
                print("da khoi phuc", p)
        return
    for p in files:                                   # luon bat dau tu ban goc
        if os.path.exists(p + BAK):
            shutil.copyfile(p + BAK, p)
        else:
            shutil.copyfile(p, p + BAK)
    new = {}
    for p, edits in EDITS.items():
        raw = read(p)
        nl = "\r\n" if "\r\n" in raw else "\n"
        s = raw.replace("\r\n", "\n")
        for i, (old, rep) in enumerate(edits):
            if s.count(old) != 1:
                sys.exit(f"{p}: khong tim thay vi tri sua #{i + 1} - ban repo co the da khac. Khong thay doi gi.")
            s = s.replace(old, rep, 1)
        new[p] = s.replace("\n", nl)
    for p, s in new.items():
        write(p, s)
    print("Xong. Khoi dong lai webui. Buoc 2: dan link anh. Buoc 5: chon Voice engine = VieNeu.")


if __name__ == "__main__":
    main()